css:
.cat-field{display:flex;flex-direction:column;gap:4px;font-family:var(--cat-font-family-ui)}
.cat-label{font-size:var(--cat-font-size-xs);font-weight:var(--cat-font-weight-medium);color:var(--cat-color-ink-mid)}
.cat-input{position:relative;display:flex;align-items:center}
.cat-input>.el{width:100%;height:var(--cat-size-control-h-md);padding:0 12px;border-radius:10px;border:1px solid var(--cat-color-stroke-input);background:var(--cat-semantic-input-a);box-shadow:var(--cat-elevation-chip-hover);font:400 var(--cat-font-size-md) var(--cat-font-family-ui);color:var(--cat-color-ink-hi);outline:none;transition:border-color var(--cat-motion-med) ease,background var(--cat-motion-med) ease,box-shadow var(--cat-motion-med) ease}
.cat-input>.el::placeholder{color:var(--cat-color-ink-low)}
.cat-input:focus-within>.el{background:linear-gradient(180deg,#fff,rgba(248,250,255,.92));border-color:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));box-shadow:0 0 0 var(--cat-size-border-focus-ring) var(--cat-semantic-accent-ring)}
.cat-input.has-icon>.el{padding-left:32px}
.cat-input>.cat-icon{position:absolute;left:10px;display:grid;place-items:center;color:var(--cat-color-ink-low);pointer-events:none}
.cat-input>.el:disabled{opacity:.5;cursor:not-allowed}
.cat-field.is-error>.cat-input>.el{border-color:var(--cat-color-danger-base)}
.field-msg{font-size:var(--cat-font-size-xs);color:var(--cat-color-danger-base)}
